cssCode:
.typing-container {
  font-size: 30px; font-weight: bold; font-family: sans-serif;
  text-align: center;
}
.typing-text {
  background: linear-gradient(to right, #60a5fa, #a855f7);
  -webkit-background-clip: text; background-clip: text; color: transparent;
}
.cursor {
  display: inline-block; width: 3px; background-color: #a855f7;
  margin-left: 5px; animation: blink 0.7s infinite;
}
@keyframes blink { 0%, 100% { opacity: 1; } 50% { opacity: 0; } }

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const wrap = document.createElement('div');
wrap.className = 'typing-container';

const textSpan = document.createElement('span');
textSpan.className = 'typing-text';

const cursorSpan = document.createElement('span');
cursorSpan.className = 'cursor';
cursorSpan.innerHTML = '&nbsp;';

wrap.appendChild(textSpan);
wrap.appendChild(cursorSpan);
c.appendChild(wrap);

const words = ['Ultra Max Premium App', 'Next-Gen Mobile UI', 'Super Smooth Animations'];
let wordIdx = 0, charIdx = 0, isDeleting = false;

function typeEffect() {
  const currentWord = words[wordIdx];
  if (isDeleting) {
    textSpan.innerText = currentWord.substring(0, charIdx - 1);
    charIdx--;
  } else {
    textSpan.innerText = currentWord.substring(0, charIdx + 1);
    charIdx++;
  }

  let typingSpeed = isDeleting ? 50 : 100;

  if (!isDeleting && charIdx === currentWord.length) {
    typingSpeed = 1500; // શબ્દ પૂરો થાય ત્યારે રોકાવું
    isDeleting = true;
  } else if (isDeleting && charIdx === 0) {
    isDeleting = false;
    wordIdx = (wordIdx + 1) % words.length;
    typingSpeed = 500;
  }
  setTimeout(typeEffect, typingSpeed);
}
typeEffect();
